      "description": "据说西岳家族是木漏隙光山的神圣守护者。确实，伊藤家族的当地开发计划让茂大为震怒。不过幸子因为和惠美的妈妈是老朋友了，对这位年轻姑娘很有好感。而且她也清楚自己孙女的心里装着谁……香织在失去父母后搬到了木漏隙光山，她很快爱上了这里的雪道，以及她祖父的世仇的儿子！她最大的愿望就是融化祖父冻结成冰的心。",
