      "worldId": "henfordonbagley",
      "image": "/images/families/Chopra.jpg",
      "description": "作为单亲妈妈，抚养拉胡尔并不容易，但拉维娜越来越喜欢这种关系，并且很享受照料村庄做个好邻居的快乐。拉胡尔很尊敬他能干的母亲，但他一直生活在这个小村庄里，他渴望出去旅行，看看大千世界。不过他也不忍心留下妈妈独自一人生活。",
