      "chineseName": "贝尔",
      "world": "Henford-on-Bagley",
      "worldId": "henfordonbagley",
      "image": "/images/families/Bell.jpg",
      "description": "比起与模拟市民相处，动物的陪伴更能给麦可带来慰藉。尽管他在约会时有些尴尬，但这样的他作为布兰伯伍德森林的生物饲养员是很称职的。多年前，他修缮了一间破败的林中小屋，从此便成为了那里各种植物和动物的非正式护理员。",
