      "image": "/images/families/Howell.jpg",
      "description": "卢来到月木锯木厂后不久，为了给约会对象赛琳留下好印象，他取笑了镇上臭名昭著的野蛮狼人格雷格。他的错误决定给他和赛琳都带来了糟糕的后果，但当她寻求解药时，卢认为他可以挺过去……结果并不像他的预期那样。这个恶作剧大师是会学着去爱内心出现的狼性呢，还是会尝试着从他陷入的麻烦中找到出路呢？",
