      "description": "幽浑家族充满了神秘色彩。有传言说，奥莉薇的前几任丈夫都死于非命，这让她现在与莱恩 科芬——枯萎逆时针乐队的创始人和唯一成员——订婚变得相当尴尬。莱恩是否知道，这位即将成为他配偶的幽浑家族一员，在她的储藏室里藏着骷髅呢？他肯定不会过多地询问她儿子尼昂的神秘身世。这么说吧，也许死神之所以不监视他们家，完全是因为奥莉薇过去的风流韵事。",
