      "image": "/images/families/Amri.jpg",
      "description": "这一切终于发生了——带着一把吉他和充满希望的乐观主义，札因鼓起勇气离开了家，去追求真正的爱好：唱歌。 当然，大多数人都无法在音乐的道路上走得很远，但如果你连尝试都不敢，又有什么意义呢？札因已经准备好迎接生活的挑战！",
