      "description": "两个性格迥异的恋人排除万难走到一起，如今拥有了一个温馨小家。托德和艾尔里克因喜爱自然与魔法而结缘，他们经常整天晒太阳，或在水畔采探。但生活不可能事事完美——托德的药剂师事业蒸蒸日上，艾尔里克则开始寻找调酒师之外的更大人生目标。他陷入了对真实自我本质的迷茫，甚至开始思索，剪断翅膀能否让自己获得更多的自由。只有时间能知道答案。",
