      "worldId": "gibbipoint",
      "image": "/images/families/Perry.jpg",
      "description": "芙丽达·佩里从没想过自己会一边经营「重燃新生健身静修营」，一边照顾她那害羞又贴心的孙子道奇——但事到如今，也只能一边兼顾了！芙丽达每天忙于飞轮课程与激励他人突破自我，同时也鼓励道奇走出户外、探索世界，也许还能唤醒他内心那位潜藏的「野孩子」。",
