      "description": "一家之长奈吉尔正在吉比吉比营地实现他儿时的梦想，担任营地主任；而他的妻子莎拉则将她对创意与混乱的热爱投入在担任营地辅导员的工作中。他们的双胞胎女儿，艾莉丝与艾琳，也常常看起来像是一对截然不同的极端姐妹花。",
